
import { defineComponent } from "vue";
import { Waypoint } from "vue-waypoint";
import HomeView from "@/views/HomeView.vue";
import AboutView from "@/views/AboutView.vue";
import ExperienceView from "@/views/ExperienceView.vue";
import SkillView from "@/views/SkillView.vue";
import WorkView from "@/views/WorkView.vue";
import SpecialExperienceView from "@/views/SpecialExperienceView.vue";

const RESUME_PDF_URL =
  "https://shaynec25.github.io/shayne/shayne_chang_resume.pdf";

export default defineComponent({
  components: {
    HomeView,
    AboutView,
    Waypoint,
    ExperienceView,
    SkillView,
    WorkView,
    SpecialExperienceView,
  },
  data() {
    return {
      isTop: true,
      navLists: [
        {
          name: "About",
          path: "#about",
        },
        {
          name: "Experience & Education",
          path: "#experienceAndEdu",
        },
        {
          name: "Skill",
          path: "#skill",
        },
        {
          name: "Works",
          path: "#works",
        },
        {
          name: "Special Experience",
          path: "#specialExperience",
        },
        {
          name: "Download My Resume",
          path: RESUME_PDF_URL,
          target: "_blank",
        },
      ],
    };
  },
  methods: {
    onChange(state: any) {
      if (state.going == "IN") {
        this.isTop = true;
      } else {
        this.isTop = false;
      }
    },
    setLang() {
      const currentLang = localStorage.getItem("set-lang");
      localStorage.setItem("set-lang", currentLang == "tw" ? "en" : "tw");
      location.reload();
    },
  },
});
